class Solution:
    def checkArray(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        diff = [0] * (n + 1)
        cur = 0
        for i in range(n):
            cur -= diff[i]
            r = nums[i] - cur
            if r < 0 or r % k:
                return False
            if r:
                if i + k > n:
                    return False
                cur += r
                diff[i + k] += r
        return True

