class Solution {
public:
    bool checkArray(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> diff(n + 1, 0);
        long long cur = 0;
        for (int i = 0; i < n; i++) {
            cur -= diff[i];
            long long r = (long long)nums[i] - cur;
            if (r < 0 || r % k) return false;
            if (r) {
                if (i + k > n) return false;
                cur += r;
                diff[i + k] += r;
            }
        }
        return true;
    }
};

