class Solution {
    public boolean checkArray(int[] nums, int k) {
        int n = nums.length;
        long[] diff = new long[n + 1];
        long cur = 0;
        for (int i = 0; i < n; i++) {
            cur -= diff[i];
            long r = nums[i] - cur;
            if (r < 0 || r % k != 0) return false;
            if (r != 0) {
                if (i + k > n) return false;
                cur += r;
                diff[i + k] += r;
            }
        }
        return true;
    }
}

