var checkArray = function(nums, k) {
    const n = nums.length;
    const diff = new Array(n + 1).fill(0);
    let cur = 0;
    for (let i = 0; i < n; i++) {
        cur -= diff[i];
        const r = nums[i] - cur;
        if (r < 0 || r % k !== 0) return false;
        if (r !== 0) {
            if (i + k > n) return false;
            cur += r;
            diff[i + k] += r;
        }
    }
    return true;
};
